// Loop over input items
for (const item of $input.all()) {

  // 1. Gather Inputs
  // Get trigger parameters from the initial trigger node
  const triggerData = $('When Executed by Another Workflow').first().json;
  // Get database row from Databricks query node
  const sqlData = item.json; 

  const row = sqlData && sqlData.order_id ? sqlData : null;

  // Format and cast all input variables exactly as defined in the skill
  const rt = String(triggerData.request_type || 'return').toLowerCase().trim(); 
  const risk = parseInt(triggerData.risk_score || 0, 10);
  const refunds90 = parseInt(triggerData.refunds_last_90d || 0, 10);
  const cust_tier = String(triggerData.tier || '').toLowerCase().trim();

  // Check item_unused: supports explicit boolean/string or inferred from customer description
  const reasonText = String(triggerData.reason_text || '').toLowerCase();
  const unusedParam = String(triggerData.item_unused).toLowerCase();
  const unused = unusedParam === 'true' || 
                 triggerData.item_unused === true || 
                 reasonText.includes('unworn') || 
                 reasonText.includes('unused') || 
                 reasonText.includes('original packaging');

  const evidence = String(triggerData.evidence_ok) === 'true' || triggerData.evidence_ok === true;
  const exception = String(triggerData.wants_exception) === 'true' || triggerData.wants_exception === true;
  const new_country = String(triggerData.new_country || '').trim().toUpperCase();

  const confirmed = String(triggerData.confirmed) === 'true' || triggerData.confirmed === true;
  const approved_by = String(triggerData.approved_by || '').trim();
  const approved = approved_by.length > 0;

  // Helper functions matching Ruby closures
  function build(decision, route, tier, reasons, amount, days_left) {
    return {
      decision: decision,
      route: route,
      tier: tier,
      refund_amount: parseFloat(amount) || 0.0,
      currency: row ? String(row.currency || '') : '',
      days_remaining: parseInt(days_left || 0, 10),
      reasons: Array.isArray(reasons) ? reasons.join('; ') : String(reasons),
      policy_version: row ? String(row.policy_version || '') : ''
    };
  }

  function decline(msg, left = 0) { 
    return build('decline', 'decline', 'T0', msg, 0, left); 
  }

  function human(msg, left = 0) { 
    return build('human', 'human', 'T3', msg, 0, left); 
  }

  function by_amount(refund, reasons, left = 0) {
    const auto_limit = parseFloat(row.auto_limit || 0);
    const approval_limit = parseFloat(row.approval_limit || 0);
    const auto_actions_30d = parseInt(row.auto_actions_30d || 0, 10);
    const max_auto_actions_30d = parseInt(row.max_auto_actions_30d || 0, 10);

    let reasonArr = Array.isArray(reasons) ? reasons : [reasons];

    if (refund <= auto_limit) {
      if (auto_actions_30d >= max_auto_actions_30d) {
        reasonArr.push('Auto-action limit reached');
        return build('eligible', 'approval', 'T2', reasonArr, refund, left);
      } else {
        return build('eligible', 'auto', 'T1', reasonArr, refund, left);
      }
    } else if (refund <= approval_limit) {
      return build('eligible', 'approval', 'T2', reasonArr, refund, left);
    } else {
      return build('human', 'human', 'T3', reasonArr, refund, left);
    }
  }

  const amount = row ? parseFloat(row.amount || 0) : 0.0;
  const fee = row ? parseFloat(row.shipping_fee || 0) : 0.0;

  // -------------------------------------------------------------
  // PART 1: Full Step-2 Business Logic Engine
  // -------------------------------------------------------------
  let decision_output;

  if (!row) {
    decision_output = decline('Order not found for this customer');
  } else if (rt !== 'address_change' && (String(row.refunded).toLowerCase() === 'yes' || parseInt(row.refund_count || 0, 10) > 0)) {
    decision_output = decline('Already refunded');
  } else if (rt !== 'address_change' && parseInt(row.return_count || 0, 10) > 0) {
    decision_output = decline('A return is already in progress for this order; the refund follows after inspection');
  } else if (row.order_status === 'cancelled') {
    decision_output = decline('Order is already cancelled');
  } else if (risk >= parseInt(row.risk_score_escalate || 0, 10) || refunds90 >= parseInt(row.serial_refund_threshold || 0, 10)) {
    decision_output = human('Risk gate: customer needs human review');
  } else if (rt === 'return') {
    if (row.order_status !== 'delivered') {
      decision_output = decline('Order not delivered yet');
    } else {
      const days = parseInt(row.days_since_delivery || 0, 10);
      const return_window_days = parseInt(row.return_window_days || 0, 10);
      const left = return_window_days - days;

      if (left < 0) {
        if (exception || cust_tier === 'vip') {
          decision_output = human(`Outside the ${return_window_days}-day window; exception request`, left);
        } else {
          decision_output = decline(`Delivered ${days} days ago; return window is ${return_window_days} days`, left);
        }
      } else if (!unused) {
        decision_output = decline('Item must be unused', left);
      } else {
        decision_output = by_amount(amount, ['Return'], left);
      }
    }
  } else if (rt === 'damaged' || rt === 'wrong_item') {
    if (row.order_status !== 'delivered') {
      decision_output = decline('Order not delivered yet');
    } else {
      const days = parseInt(row.days_since_delivery || 0, 10);
      const damage_report_days = parseInt(row.damage_report_days || 0, 10);
      if (days > damage_report_days) {
        decision_output = human(`Reported ${days} days after delivery; limit is ${damage_report_days} days`);
      } else if (!evidence) {
        decision_output = build('need_evidence', 'need_evidence', 'T0', 'Need a specific description or photo of the problem', 0, 0);
      } else {
        decision_output = by_amount(amount + fee, [`${rt} refund including shipping`], 0);
      }
    }
  } else if (rt === 'delayed') {
    const late = parseInt(row.days_late || 0, 10);
    const delay_threshold_days = parseInt(row.delay_threshold_days || 0, 10);
    if (late <= delay_threshold_days) {
      decision_output = decline(`${late} days late; threshold is ${delay_threshold_days}. Share the ETA`);
    } else {
      decision_output = by_amount(amount + fee, [`Delayed ${late} days`], 0);
    }
  } else if (rt === 'lost') {
    if (row.ship_status !== 'lost') {
      decision_output = decline('Carrier has not marked it lost');
    } else {
      decision_output = by_amount(amount + fee, ['Lost in transit'], 0);
    }
  } else if (rt === 'not_received') {
    if (row.ship_status !== 'delivered') {
      decision_output = decline('Carrier does not show it delivered; use tracking');
    } else if (row.claim_status === 'raised') {
      decision_output = decline('A carrier claim is already open');
    } else {
      decision_output = build('eligible', 'auto', 'T1', 'Raise a carrier claim; follow up within 48 hours; no instant refund', 0, 0);
    }
  } else if (rt === 'cancel') {
    if (!['payment_pending', 'packed'].includes(row.order_status)) {
      decision_output = decline('Already shipped or delivered; cannot cancel');
    } else {
      const refund = row.payment_method === 'cod' ? 0.0 : amount + fee;
      decision_output = by_amount(refund, ['Cancellation'], 0);
    }
  } else if (rt === 'address_change') {
    if (new_country !== '' && new_country !== String(row.country || '').toUpperCase()) {
      decision_output = human('Address in a different country needs human review');
    } else if (['payment_pending', 'packed'].includes(row.order_status)) {
      decision_output = build('eligible', 'auto', 'T1', 'Not dispatched yet; address can be changed now', 0, 0);
    } else if (row.order_status === 'shipped') {
      decision_output = build('eligible', 'approval', 'T2', 'Already shipped; needs a carrier intercept request. Fee may apply and it is not guaranteed', 0, 0);
    } else {
      decision_output = decline(`Order is ${row.order_status}; address cannot be changed`);
    }
  } else {
    decision_output = decline('Unknown request type');
  }

  // -------------------------------------------------------------
  // PART 2: Full Step-3 Validation Engine
  // -------------------------------------------------------------
  let validation_output = {};
  const reasons_str = String(decision_output.reasons || '').toLowerCase();

  if (!confirmed) {
    validation_output = { 
      allowed: false, 
      already_done: false, 
      message: 'The customer has not confirmed yet.' 
    };
  } else if (decision_output.decision !== 'eligible') {
    validation_output = {
      allowed: false,
      already_done: reasons_str.includes('already'),
      message: `Not allowed: ${decision_output.reasons}`
    };
  } else if (decision_output.route === 'auto' || (decision_output.route === 'approval' && approved)) {
    validation_output = { 
      allowed: true, 
      already_done: false, 
      message: 'OK' 
    };
  } else {
    validation_output = { 
      allowed: false, 
      already_done: false, 
      message: 'This needs approval or a person. Escalate instead.' 
    };
  }

  // -------------------------------------------------------------
  // PART 3: Expose Outputs to n8n
  // -------------------------------------------------------------
  item.json.decision_output = decision_output;
  item.json.validation_output = validation_output;

  // Flattened outputs for simple referencing in n8n nodes
  item.json.allowed = validation_output.allowed;
  item.json.already_done = validation_output.already_done;
  item.json.message = validation_output.message;
  item.json.refund_amount = decision_output.refund_amount;
  item.json.currency = decision_output.currency;
  item.json.decision = decision_output.decision;
  item.json.route = decision_output.route;
  item.json.reasons = decision_output.reasons;
}

return $input.all();

